370	    const floor = this.floorInput().trim();
371	    const proofThreshold = this.proofThresholdInput().trim();
372	    // With nothing typed since the last save, saving sets the clerk limit again as it stands.
373	    const terms = this.termsInput().trim();
374	    const latePct = this.latePctInput().trim();
375	    const policyDate = this.policyDateInput().trim();
376	    const periodNumberingFrom = this.periodNumberingFromInput().trim();
377	    const saveLimit =
378	      this.limitEdited ||
379	      (!this.capEdited && !this.proofThresholdEdited && !this.floorEdited && !this.termsEdited && this.gradeTermsEdited.size === 0 && !this.latePctEdited && !this.policyDateEdited &&
380	        !this.periodNumberingFromEdited && this.permissionsEdited.size === 0);
381	    const saveCap = this.capEdited;
382	    const saveProofThreshold = this.proofThresholdEdited;
383	    const saveFloor = this.floorEdited;
384	    const saveTerms = this.termsEdited;
385	    const saveGradeTerms = GRADES.filter((g) => this.gradeTermsEdited.has(g))
386	      .map((g) => ({ grade: g, value: this.gradeTermsInput()[g].trim() }));
387	    const saveLatePct = this.latePctEdited;
388	    const savePolicyDate = this.policyDateEdited;
389	    const savePeriodNumberingFrom = this.periodNumberingFromEdited;
390	    const savePermissions = PERMISSION_ACTIONS.filter((a) => this.permissionsEdited.has(a))
391	      .map((a) => ({ action: a, value: this.permissionInput()[a].trim() }));
392	    const froms = this.fromInput();
393	    const from = (key: DatedKey) => froms[key].trim();
394	    const savedKeys: DatedKey[] = [
395	      ...(saveLimit ? (['clerk-limit'] as const) : []),
396	      ...(saveCap ? (['cap'] as const) : []),
397	      ...(saveProofThreshold ? (['proof-threshold'] as const) : []),
398	      ...(saveFloor ? (['floor'] as const) : []),
399	      ...(saveTerms ? (['terms'] as const) : []),
400	      ...saveGradeTerms.map((t) => this.gradeKey(t.grade)),
401	      ...(saveLatePct ? (['late-pct'] as const) : []),
402	    ];
403	    if (savedKeys.some((key) => !SETTING_FROM.test(from(key)))) {
404	      this.settingsError.set('Type a from-date as yyyy-mm-dd, or leave it empty for the sheet\'s today.');
405	      return;
406	    }
407	    if (saveLimit && !LIMIT.test(limit)) {
408	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it empty for no limit.');
409	      return;
410	    }
411	    if (saveCap && !CAP.test(cap)) {
412	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it empty for no cap.');
413	      return;
414	    }
415	    if (saveProofThreshold && !PROOF_THRESHOLD.test(proofThreshold)) {
416	      this.settingsError.set('Type a proof threshold of 0.00 or more, with up to two decimals, or leave it empty for none.');
417	      return;
418	    }
419	    if (saveFloor && !FLOOR.test(floor)) {
420	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
421	      return;
422	    }
423	    if (saveTerms && !TERMS.test(terms)) {
424	      this.settingsError.set('Type terms as a whole number of days.');
425	      return;
426	    }
427	    if (saveGradeTerms.some((t) => !GRADE_TERMS.test(t.value))) {
428	      this.settingsError.set('Type a grade\'s terms as a whole number of days, or leave them empty for the sheet\'s terms.');
429	      return;
430	    }
431	    if (saveLatePct && !LATE_PCT.test(latePct)) {
432	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
433	      return;
434	    }
435	    if (savePolicyDate && !POLICY_DATE.test(policyDate)) {
436	      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it empty for the sheet\'s today.');
437	      return;
438	    }
439	    if (savePeriodNumberingFrom && !PERIOD_NUMBERING_FROM.test(periodNumberingFrom)) {
440	      this.settingsError.set('Type the date period numbering is from as yyyy-mm-dd, or leave it empty for off.');
441	      return;
442	    }
443	    if (savePermissions.some((p) => !PERMISSION.test(p.value))) {
444	      this.settingsError.set('Type the roles that may take an action as clerk or steward, comma separated, or leave them empty for the standing rule.');
445	      return;
446	    }
447	    // What was typed is taken now: anything typed meanwhile is saved by the next submit.
448	    if (saveLimit) this.limitEdited = false;
449	    if (saveCap) this.capEdited = false;
450	    if (saveProofThreshold) this.proofThresholdEdited = false;
451	    if (saveFloor) this.floorEdited = false;
452	    if (saveTerms) this.termsEdited = false;
453	    for (const t of saveGradeTerms) this.gradeTermsEdited.delete(t.grade);
454	    if (saveLatePct) this.latePctEdited = false;
455	    if (savePolicyDate) this.policyDateEdited = false;
456	    if (savePeriodNumberingFrom) this.periodNumberingFromEdited = false;
457	    for (const p of savePermissions) this.permissionsEdited.delete(p.action);
458	    this.fromInput.update((all) => {
459	      const next = { ...all };
460	      for (const key of savedKeys) next[key] = '';
461	      return next;
462	    });
463	    const write = async () => {
464	      try {
465	        if (saveLimit) {
466	          this.inForce(await this.api.setClerkLimit(sheet, limit, from('clerk-limit')));
467	        }
468	        if (saveCap) {
469	          const view = await this.api.setCap(sheet, cap, from('cap'));
470	          this.inForce(view);
471	          if (!this.capEdited) this.capInput.set(view.cap ?? '');
472	        }
473	        if (saveProofThreshold) {
474	          const view = await this.api.setProofThreshold(sheet, proofThreshold, from('proof-threshold'));
475	          this.inForce(view);
476	          if (!this.proofThresholdEdited) this.proofThresholdInput.set(view.proofThreshold ?? '');
477	        }
478	        if (saveFloor) {
479	          this.inForce(await this.api.setFloor(sheet, floor, from('floor')));
480	        }
481	        if (saveTerms) {
482	          this.inForce(await this.api.setTerms(sheet, terms, from('terms')));
483	        }
484	        for (const t of saveGradeTerms) {
485	          this.inForce(await this.api.setGradeTerms(sheet, t.grade, t.value, from(this.gradeKey(t.grade))));
486	        }
487	        if (saveLatePct) {
488	          this.inForce(await this.api.setLatePct(sheet, latePct, from('late-pct')));
489	        }
490	        if (savePolicyDate) {
491	          const view = await this.api.setPolicyDate(sheet, policyDate);
492	          this.session.policyDate.set(view.policyDate ?? '');
493	          if (!this.policyDateEdited) this.policyDateInput.set(view.policyDate ?? '');
494	        }
495	        if (savePeriodNumberingFrom) {
496	          const view = await this.api.setPeriodNumberingFrom(sheet, periodNumberingFrom);
497	          this.periodNumberingFrom.set(view.periodNumberingFrom ?? '');
498	          if (!this.periodNumberingFromEdited) this.periodNumberingFromInput.set(view.periodNumberingFrom ?? '');
499	        }
500	        for (const p of savePermissions) {
501	          const view = await this.api.setPermission(sheet, p.action, p.value);
502	          this.permissions.set(view.permissions);
503	          if (!this.permissionsEdited.has(p.action)) {
504	            this.permissionInput.update((all) => ({ ...all, [p.action]: view.permissions[p.action] }));
505	          }
506	        }
507	      } catch {
508	        this.settingsError.set('The settings could not be saved.');
509	      }
510	    };
511	    this.saving = this.saving.then(write);
512	    await this.saving;
513	  }
514	
515	  protected async saveRole(event: Event): Promise<void> {
516	    event.preventDefault();
517	    if (this.busy) return;
518	    this.roleError.set(null);
519	    const sheet = this.session.sheet();
520	    if (!sheet) return;
521	    const user = this.roleUser().trim();
522	    const role = this.roleName().trim();
523	    if (!user) {
524	      this.roleError.set('Type the user name to set a role for.');
525	      return;
526	    }
527	    if (!(ROLES as readonly string[]).includes(role)) {
528	      this.roleError.set(`A role is ${this.roleNames}.`);
529	      return;
530	    }
531	    this.busy = true;
532	    try {
533	      const saved = await this.api.setRole(sheet, { user, role: role as RoleName });
534	      this.roles.update((all) =>
535	        [...all.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
536	      );
537	      this.roleUser.set('');
538	      this.roleName.set('');
539	    } catch {
540	      this.roleError.set(`The role of ${user} could not be set.`);
541	    } finally {
542	      this.busy = false;
543	    }
544	  }
545	
546	  /** Show the dated settings as in force on the sheet's today, and the floor's and late percent's values by from-date. */
547	  private inForce(view: SettingsView): void {
548	    this.clerkLimit.set(view.clerkLimit);
549	    this.session.cap.set(view.cap ?? '');
550	    this.proofThreshold.set(view.proofThreshold);
551	    this.session.floor.set(view.floor);
552	    this.session.floorHistory.set(view.floorHistory);
553	    this.session.terms.set(view.terms);
554	    this.gradeTerms.set({ A: view.termsA, B: view.termsB, C: view.termsC });
555	    this.session.latePct.set(view.latePct);
556	    this.session.latePctHistory.set(view.latePctHistory);
557	  }
558	
559	  /** The sheet's today changed: re-read which values are in force on it. */
560	  private async todayChanged(sheet: string): Promise<void> {
561	    const settings = await this.api.get(sheet);
562	    if (this.session.sheet() === sheet) this.inForce(settings);
563	  }
564	
565	  private async reload(sheet: string, loads: number): Promise<void> {
566	    const [settings, roles] = await Promise.all([this.api.get(sheet), this.api.roles(sheet)]);
567	    // A later load may have started while this one was in flight: only the latest is shown.
568	    if (this.session.sheet() === sheet && this.session.loads() === loads) {
569	      this.inForce(settings);
570	      // The cap's input starts at the cap in force, so clearing it is a change.
571	      this.capInput.set(settings.cap ?? '');
572	      this.capEdited = false;
573	      // So does the proof threshold's.
574	      this.proofThresholdInput.set(settings.proofThreshold ?? '');
575	      this.proofThresholdEdited = false;
576	      this.session.policyDate.set(settings.policyDate ?? '');
577	      // The policy date's input starts at the date in force, so clearing it is a change.
578	      this.policyDateInput.set(settings.policyDate ?? '');
579	      this.policyDateEdited = false;
580	      // Period numbering from starts at the date in force too, so clearing it is a change.
581	      this.periodNumberingFrom.set(settings.periodNumberingFrom ?? '');
582	      this.periodNumberingFromInput.set(settings.periodNumberingFrom ?? '');
583	      this.periodNumberingFromEdited = false;
584	      // Each action's roles start at those in force, so clearing them is a change.
585	      this.permissions.set(settings.permissions);
586	      this.permissionInput.set({ ...settings.permissions });
587	      this.permissionsEdited.clear();
588	      this.roles.set(roles);
589	    }
590	  }

